import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./NumericInput.stories";
import NumericInput from ".";

const { Basic } = composeStories(stories) as any;

describe("NumericInput", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<NumericInput data-testid="numericinput" />);
    expect(screen.getByTestId("numericinput")).toBeTruthy();
  });

  it("display warnings with invalid props", () => {
    render(<NumericInput defaultValue={110} min={10} max={100} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(
      /expects the `defaultValue` prop to be contained in `min` and `max` range/
    );

    render(<NumericInput step={-10} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(2);
    expect(consoleSpy.warn.mock.calls[1][0]).toMatch(
      /expects the `step` prop to be greater than zero/
    );

    render(<NumericInput step={3} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(3);
    expect(consoleSpy.warn.mock.calls[2][0]).toMatch(
      /expects the `min` and `max` range to be evenly divisible by the `step` prop/
    );
  });

  it("allow keyboard navigation", async () => {
    const callback = jest.fn();
    render(<NumericInput step={10} onChange={callback} />);
    const input = screen.getByRole("spinbutton");
    await userEvent.tab();
    expect(input).toHaveFocus();

    fireEvent.keyDown(input, { key: "ArrowUp" });
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(10);

    fireEvent.keyDown(input, { key: "ArrowUp" });
    fireEvent.keyDown(input, { key: "ArrowRight" });
    expect(callback).toHaveBeenCalledTimes(3);
    expect(callback).toHaveBeenLastCalledWith(30);

    fireEvent.keyDown(input, { key: "ArrowDown" });
    fireEvent.keyDown(input, { key: "ArrowLeft" });
    expect(callback).toHaveBeenCalledTimes(5);
    expect(callback).toHaveBeenLastCalledWith(10);
  });

  it("clamp incremented values in min/max range", () => {
    const callback = jest.fn();
    render(<NumericInput max={10} defaultValue={12} onChange={callback} />);
    fireEvent.click(screen.getByRole("button", { name: /Increase/ }));
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(10);
  });

  it("clamp decremented values in min/max range", () => {
    const callback = jest.fn();
    render(<NumericInput max={10} defaultValue={12} onChange={callback} />);
    fireEvent.click(screen.getByRole("button", { name: /Decrease/ }));
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(10);
  });

  it("allow text input", async () => {
    const callback = jest.fn();
    render(<NumericInput min={1} onChange={callback} />);
    const input = screen.getByRole("spinbutton");

    await userEvent.type(input, "0", { initialSelectionStart: 1 });
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(10);

    await userEvent.clear(input);
    expect(callback).toHaveBeenCalledTimes(2);
    expect(callback).toHaveBeenLastCalledWith(1);

    await userEvent.type(input, "1000");
    expect(callback).toHaveBeenCalledTimes(6);
    // clamped to default max value
    expect(callback).toHaveBeenLastCalledWith(100);

    await userEvent.clear(input);
    await userEvent.type(input, "0");
    expect(callback).toHaveBeenCalledTimes(8);
    expect(callback).toHaveBeenLastCalledWith(10);
  });

  it("allow decimal input", async () => {
    const callback = jest.fn();
    render(<NumericInput step={0.1} onChange={callback} />);
    const input = screen.getByRole("spinbutton");

    await userEvent.type(input, "0.1");
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(0.1);

    await userEvent.clear(input);
    await userEvent.type(input, "4");
    expect(callback).toHaveBeenCalledTimes(3);
    expect(callback).toHaveBeenLastCalledWith(4);

    await userEvent.clear(input);
    await userEvent.type(input, "0.16");
    expect(callback).toHaveBeenCalledTimes(6);
    expect(callback).toHaveBeenLastCalledWith(0.2);
  });

  it("allow forwardRef", () => {
    const NumericInputWithRef = () => {
      const numericInputRef = React.useRef<HTMLInputElement>(null);
      React.useEffect(() => {
        numericInputRef.current && numericInputRef.current.focus();
      }, []);
      return <NumericInput ref={numericInputRef} />;
    };

    render(<NumericInputWithRef />);
    expect(screen.getByRole("spinbutton")).toHaveFocus();
  });
});
